                <Link to="/lookup" onClick={() => setUserMenuOpen(false)} className="flex items-center gap-3 rounded-lg px-3 py-2.5 hover:bg-white/[0.05] transition-colors group">
                  <span className="grid h-8 w-8 place-items-center rounded-md bg-white/[0.04] border border-white/10 shrink-0"><Wrench className="w-4 h-4 text-zinc-400" /></span>
                  <span className="flex-1 text-left font-mono text-sm text-zinc-200 group-hover:text-white">Advanced lookup</span>
                </Link>
                <button
